/** The `agents.*` operations. */
export class AgentsOperations {
  readonly #runner: Runner;

  /** @internal */
  constructor(runner: Runner) {
    this.#runner = runner;
  }

  /**
   * List the agents.
   */
  list(
    input: {
      /** The agents to cover, by ID, given once for each. Each covers its conversations too. Every agent you may see unless set. */
      agents?: string[] | undefined;
    } = {},
    options: CallOptions = {},
  ): Promise<Outputs["agents.list"]> {
    return this.#runner.call("agents.list", { ...input }, options);
  }

  /**
   * Forget the agents.
   *
   * Each agent goes as agent.forget takes it: stopped, with its conversation, definition and triggers deleted.
   */
  forget(
    input: {
      /** The agents to cover, by ID, given once for each. Each covers its conversations too. Every agent you may see unless set. */
      agents?: string[] | undefined;
    } = {},
    options: CallOptions = {},
  ): Promise<Outputs["agents.forget"]> {
    return this.#runner.call("agents.forget", { ...input }, options);
  }

  /**
   * Stop what the agents are doing.
   */
  cancel(
    input: {
      /** The agents to cover, by ID, given once for each. Each covers its conversations too. Every agent you may see unless set. */
      agents?: string[] | undefined;
    } = {},
    options: CallOptions = {},
  ): Promise<Outputs["agents.cancel"]> {
    return this.#runner.call("agents.cancel", { ...input }, options);
  }
}

